    ctx.stroke();
    ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(headTop[0], headTop[1]); ctx.lineTo(headBot[0], headBot[1]); ctx.stroke();
    // 前叉
    ctx.strokeStyle = '#cfd4da'; ctx.lineWidth = 3.5;
    ctx.beginPath(); ctx.moveTo(headBot[0], headBot[1]); ctx.quadraticCurveTo(98, -18, front[0], front[1]); ctx.stroke();
    // 座杆 & 座垫
    ctx.strokeStyle = '#999'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(seatTop[0], seatTop[1]); ctx.lineTo(28, -55); ctx.stroke();
    ctx.fillStyle = '#222';
    ctx.beginPath(); ctx.moveTo(16, -57); ctx.quadraticCurveTo(28, -62, 40, -57); ctx.lineTo(16, -54); ctx.fill();
    // 车把
    ctx.strokeStyle = '#999'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(headTop[0], headTop[1]); ctx.lineTo(87, -62); ctx.stroke();
    ctx.strokeStyle = '#222'; ctx.lineWidth = 3.5;
    ctx.beginPath(); ctx.moveTo(80, -64); ctx.quadraticCurveTo(90, -66, 92, -60); ctx.stroke();
    // 挡泥板
    ctx.strokeStyle = '#2c3e50'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.arc(rear[0], rear[1], R + 5, Math.PI * 1.05, Math.PI * 1.6); ctx.stroke();
    ctx.beginPath(); ctx.arc(front[0], front[1], R + 5, Math.PI * 1.4, Math.PI * 1.95); ctx.stroke();
    // 车篮
    ctx.strokeStyle = '#a0522d'; ctx.lineWidth = 2;
    ctx.strokeRect(94, -62, 18, 14);
    ctx.beginPath(); ctx.moveTo(100, -62); ctx.lineTo(100, -48); ctx.moveTo(106, -62); ctx.lineTo(106, -48); ctx.stroke();
    ctx.fillStyle = '#27ae60';
    ctx.beginPath(); ctx.arc(100, -64, 4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#f39c12';
    ctx.beginPath(); ctx.arc(107, -65, 4, 0, Math.PI * 2); ctx.fill();

    // ---- 链条 & 牙盘 ----
    ctx.strokeStyle = '#444'; ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(bb[0], bb[1] - 9); ctx.lineTo(rear[0], rear[1] - 4);
    ctx.moveTo(bb[0], bb[1] + 9); ctx.lineTo(rear[0], rear[1] + 4);
    ctx.stroke();
    // 链条滚动小点
    ctx.fillStyle = '#777';
    const chainOff = (dist / S * 0.5) % 6;
    for (let i = 0; i < 7; i++) {
      const p = ((i * 6 + chainOff) % 40) / 40;
      ctx.fillRect(bb[0] + (rear[0] - bb[0]) * p - 0.8, bb[1] - 9 + (rear[1] - 4 - bb[1] + 9) * p - 0.8, 1.6, 1.6);
    }
    ctx.strokeStyle = '#666'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(bb[0], bb[1], 9, 0, Math.PI * 2); ctx.stroke();
    ctx.save(); ctx.translate(bb[0], bb[1]); ctx.rotate(crank);
    ctx.strokeStyle = '#888'; ctx.lineWidth = 1.2;
    for (let i = 0; i < 5; i++) { ctx.rotate(Math.PI * 2 / 5); ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(8, 0); ctx.stroke(); }
    ctx.restore();

    // ---- 身体 ----
    // 围巾(飘动)
    const neck = [shoulder[0] + 2, shoulder[1] - 4];
    ctx.strokeStyle = '#f1c40f'; ctx.lineWidth = 4; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(neck[0], neck[1]);
    for (let i = 1; i <= 6; i++) {
      ctx.lineTo(neck[0] - i * 7, neck[1] + i * 1.5 + Math.sin(t * 12 - i * 0.9) * (i * 0.9));
    }
    ctx.stroke();

    // 远侧手臂
    const eFar = ik(shoulder[0] - 2, shoulder[1], hand[0] - 3, hand[1], 22, 22, false);
    limb([shoulder[0] - 2, shoulder[1]], eFar, [hand[0] - 3, hand[1]], '#c8564b', 7, 6);

    // 躯干
    ctx.strokeStyle = '#e74c3c'; ctx.lineWidth = 16; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(hip[0], hip[1]); ctx.quadraticCurveTo(38, -88 + bob, shoulder[0], shoulder[1]); ctx.stroke();
    ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(hip[0] + 4, hip[1] - 6); ctx.quadraticCurveTo(40, -84 + bob, shoulder[0] - 3, shoulder[1] + 4); ctx.stroke();

    // 头
    const head = [shoulder[0] + 10, shoulder[1] - 17];
    ctx.fillStyle = '#f5c6a0';
    ctx.beginPath(); ctx.arc(head[0], head[1], 10, 0, Math.PI * 2); ctx.fill();
