    ctx.fillStyle = '#3b2a1e';
    ctx.beginPath(); ctx.arc(head[0] - 1, head[1] - 2, 10, Math.PI * 0.95, Math.PI * 1.9); ctx.fill();
    ctx.beginPath();
    ctx.moveTo(head[0] - 9, head[1] - 4);
    ctx.quadraticCurveTo(head[0] - 20, head[1] - 2 + Math.sin(t * 10) * 2, head[0] - 24, head[1] + 4 + Math.sin(t * 10 + 1) * 3);
    ctx.quadraticCurveTo(head[0] - 14, head[1] + 2, head[0] - 8, head[1] + 3);
    ctx.fill();
