    ctx.fillStyle = '#111';
    ctx.fillRect(head[0] + 3, head[1] - 1, 7, 3);

    // ---- 近侧腿 ----
    const kNear = ik(hip[0], hip[1], pNear[0], pNear[1], L1, L2, true);
    limb(hip, kNear, pNear, '#2c5d8f', 12, 10);
