    ctx.strokeStyle = '#aaa'; ctx.lineWidth = 3.5;
    ctx.beginPath(); ctx.moveTo(bb[0], bb[1]); ctx.lineTo(pNear[0], pNear[1]); ctx.stroke();
    ctx.fillStyle = '#222'; ctx.fillRect(pNear[0] - 6, pNear[1] + 1, 12, 3);
