    ctx.beginPath(); ctx.arc(bb[0], bb[1], 3, 0, Math.PI * 2); ctx.fill();

    // 近侧手臂
    const eNear = ik(shoulder[0], shoulder[1], hand[0], hand[1], 22, 22, false);
    limb(shoulder, eNear, hand, '#f5c6a0', 8, 7);
    ctx.strokeStyle = '#e74c3c'; ctx.lineWidth = 9;
    ctx.beginPath(); ctx.moveTo(shoulder[0], shoulder[1]);
    ctx.lineTo(shoulder[0] + (eNear[0] - shoulder[0]) * 0.45, shoulder[1] + (eNear[1] - shoulder[1]) * 0.45); ctx.stroke();
    ctx.fillStyle = '#f5c6a0';
    ctx.beginPath(); ctx.arc(hand[0], hand[1], 4, 0, Math.PI * 2); ctx.fill();

    ctx.restore();

    // 速度线
    ctx.strokeStyle = 'rgba(255,255,255,0.45)';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    const k = speed / 200;
    for (let i = 0; i < 4; i++) {
      const yy = groundY - R * S * (0.6 + i * 0.7);
      const ph = (t * 3 + i * 0.37) % 1;
      const len = (30 + i * 10) * S * k;
      const xx = x - 30 * S - ph * 80 * S;
      ctx.globalAlpha = (1 - ph) * Math.min(1, k);
      ctx.beginPath(); ctx.moveTo(xx, yy); ctx.lineTo(xx - len, yy); ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }

  // ---------- 主循环 ----------
  function frame(now) {
    let dt = (now - last) / 1000;
    last = now;
    if (dt > 0.1) dt = 0.1;
    t += dt;
    speed += (targetSpeed - speed) * Math.min(1, dt * 2);
    dist += speed * dt;

    const L = layout();
    ctx.clearRect(0, 0, W, H);
    const sun = drawSky(L);
    drawClouds(L);
    drawGulls(L);
    drawIslands(L);
    drawSea(L, sun);
    drawBeach(L);
    drawPalms(L);
    drawRail(L);
    drawRoad(L);

    const S = Math.max(0.6, Math.min(W, H) / 520);
    const groundY = L.roadTop + (L.roadBot - L.roadTop) * 0.62;
    drawRider(W * 0.38, groundY, S);

    drawForeground(L);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
